import{z as n,x as i,o as A,c as D,q as r,j as s,D as e,d as B,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"看门狗与失效安全","description":"","frontmatter":{"title":"看门狗与失效安全","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-watchdog-failsafe.md","filePath":"cs/emb-watchdog-failsafe.md","lastUpdated":1791063341000}'),d={name:"cs/emb-watchdog-failsafe.md"};function p(C,E,m,c,h,f){const t=i("Mermaid");return A(),D("div",null,[E[2]||(E[2]=r('<h1 id="看门狗与失效安全" tabindex="-1">看门狗与失效安全 <a class="header-anchor" href="#看门狗与失效安全" aria-label="Permalink to &quot;看门狗与失效安全&quot;">​</a></h1><div class="epigraph"><p>看门狗回答的不是「程序会不会挂」，而是「挂了之后世界怎么办」：喂狗是承诺，超时是违约，复位是补救——三件事要在出事前就设计好。</p><footer>—— 据各 MCU 参考手册的 IWDG/WWDG 章节；IEC 61508 失效安全概念整理</footer></div><p><a href="/cs/emb-power-management">上一课</a>把芯片的大半时间送进了深睡，设备越来越自主：现场没有人按复位键，失效只能自己兜住。而失效的形式很朴素——等一个永不置位的标志、跑飞的指针跳进数据区、<a href="/cs/soft-error-ecc">软错误</a>翻转指令位、电源跌落让状态机走进半途。缺口是一根<strong>独立于软件死活的线</strong>：无论代码卡在哪，硬件都能在时限内把系统拉回已知状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>很多人把看门狗写成「定时器中断里喂一下」，这恰好把它的价值喂没了：能准时进中断喂狗，恰恰证明中断和定时器还活着；真正的故障——主循环死锁、任务饿死、状态机卡住——往往发生在中断照常运行的背景之下。缺口有两层。第一层是<strong>喂狗策略</strong>：喂狗必须绑定「业务真的在推进」的证据，而不是「CPU 还在执行指令」。第二层是<strong>复位之后</strong>：复位不是终点，是失忆的重启——若没有失效日志与安全状态的设计，设备会带着同一个 bug 无限循环重启，用户看到的就是「永远在重连」。</p><p><span class="marginnote">看门狗本质是一个软件关不掉的倒计时器：启动后一直往下数，数到零就强制复位整块芯片。软件唯一的活路是定期把它「喂」回去重新计数——像养了一条定时喂食的狗，忘喂一次，它就把整个系统咬重启。独立于软件死活，正是它的全部价值。</span></p><h3 id="窗口看门狗补上另一半" tabindex="-1">窗口看门狗补上另一半 <a class="header-anchor" href="#窗口看门狗补上另一半" aria-label="Permalink to &quot;窗口看门狗补上另一半&quot;">​</a></h3><p>普通看门狗只惩罚「来不及喂」，不惩罚「喂得太勤」。跑飞的代码若恰好落在喂狗寄存器的写操作上，或被放进高频定时器里无条件执行，超时永远不触发，看门狗形同虚设。窗口看门狗加一条下界：早于窗口打开就喂，同样复位。喂狗因此被夹进一个时间区间——太慢是违约，太快也是违约，盲目喂狗的路径被硬件直接判死。</p><p><span class="marginnote">窗口看门狗像考勤打卡：上班前太早打卡算无效（喂太早），下班不打卡算旷工（喂太晚），只有正常时段的打卡才认——「顺手打个卡」的混日子路径被制度直接判死。喂狗从「做过一个动作」升级成「业务以正常节奏推进的证据」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地按四步。第一步分域：看门狗用独立时钟（片内低速 RC），主时钟、锁相环、软件全挂掉它照常倒数；超时按「最坏一次合法业务循环」的数倍设定。第二步定喂狗点：喂狗函数由主循环或看门狗任务调用，喂之前先核对各任务心跳——每个任务周期性刷新自己的心跳位，全部存活才喂；任何一块业务卡死，狗就饿着。第三步定安全状态：复位前把继电器断开、电机使能拉低、输出锁到无害值——「失效安全」的含义是失效后落在安全的一侧，不是简单地重启。第四步留证据：复位原因寄存器区分上电、看门狗、软复位与欠压，看门狗复位时把关键状态写进不掉电的备份区，供下次启动上报。</p>',11)),(A(),s(o,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HB%5B%22%E5%90%84%E4%BB%BB%E5%8A%A1%E5%88%B7%E6%96%B0%E5%BF%83%E8%B7%B3%E4%BD%8D%22%5D%20--%3E%20CHK%7B%22%E7%9C%8B%E9%97%A8%E7%8B%97%E4%BB%BB%E5%8A%A1%E6%A0%B8%E5%AF%B9%E5%BF%83%E8%B7%B3%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%85%A8%E9%83%A8%E5%AD%98%E6%B4%BB%22%7C%20FEED%5B%22%E5%96%82%E7%8B%97%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%9C%89%E4%BB%BB%E5%8A%A1%E5%8D%A1%E6%AD%BB%22%7C%20SKIP%5B%22%E4%B8%8D%E5%96%82%EF%BC%8C%E5%80%92%E6%95%B0%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20SKIP%20--%3E%20TOUT%5B%22%E8%B6%85%E6%97%B6%EF%BC%9A%E5%85%88%E8%90%BD%E5%AE%89%E5%85%A8%E7%8A%B6%E6%80%81%E5%86%8D%E5%A4%8D%E4%BD%8D%22%5D%0A%20%20TOUT%20--%3E%20LOG%5B%22%E8%AE%B0%E5%BD%95%E5%A4%8D%E4%BD%8D%E5%8E%9F%E5%9B%A0%E4%B8%8E%E7%8E%B0%E5%9C%BA%22%5D%0A%20%20LOG%20--%3E%20BOOT%5B%22%E5%90%AF%E5%8A%A8%E4%BB%A3%E7%A0%81%E5%88%A4%E5%9B%A0%EF%BC%8C%E8%B5%B0%E6%81%A2%E5%A4%8D%E8%B7%AF%E5%BE%84%22%5D%0A%20%20FEED%20--%3E%20HB%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"STM32 的独立看门狗跑在约 32 kHz 的片内低速 RC 上，超时可从毫秒级调到 32 秒；窗口看门狗是 7 位计数器，窗口只有毫秒量级，专盯主循环节奏。两颗狗超时相差百倍，用的正是「独立域」与「窗口」两个正交机制。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[B("看门狗的机制价值来自"),a("strong",null,"信任域的分离"),B("：计数器住在与主系统不同的时钟域，软件再乱也改不了它的倒数——软件定时器与被监控的代码共享同一个死法。窗口约束把「喂狗」从动作升级成"),a("strong",null,"证据"),B("：只有业务以正常节奏推进，喂狗事件才落进窗口。失效安全的梯子——检测、遏制、复位、带记忆的恢复——每级都要单独设计；漏掉恢复一级，设备就会在「复位—复现—复位」里打转。深睡设备还要把狗与功耗一起算：独立看门狗阻止最深的睡眠档，待机档下它本身也停，唤醒后的首轮自检要接替它站岗。")],-1)),(A(),s(o,null,{default:e(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%96%82%E7%8B%97%E4%BA%8B%E4%BB%B6%E8%90%BD%E5%9C%A8%E6%97%B6%E9%97%B4%E8%BD%B4%E5%93%AA%E9%87%8C%EF%BC%9F%22%5D%20--%3E%20E1%5B%22%E7%AA%97%E5%8F%A3%E6%89%93%E5%BC%80%E4%B9%8B%E5%89%8D%E5%96%82%EF%BC%9A%E7%AB%8B%E5%8D%B3%E5%A4%8D%E4%BD%8D%22%5D%0A%20%20T%20--%3E%20E2%5B%22%E7%AA%97%E5%8F%A3%E6%9C%9F%E5%86%85%E5%96%82%EF%BC%9A%E6%AD%A3%E5%B8%B8%EF%BC%8C%E7%8B%97%E9%87%8D%E6%96%B0%E8%AE%A1%E6%95%B0%22%5D%0A%20%20T%20--%3E%20E3%5B%22%E8%B6%85%E6%97%B6%E4%BB%8D%E6%9C%AA%E5%96%82%EF%BC%9A%E5%A4%8D%E4%BD%8D%E5%B9%B6%E8%90%BD%E5%AE%89%E5%85%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20E1%20--%3E%20W1%5B%22%E5%A0%B5%E4%BD%8F%E8%B7%91%E9%A3%9E%E4%BB%A3%E7%A0%81%E7%9B%B2%E7%9B%AE%E5%86%99%E5%96%82%E7%8B%97%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20E2%20--%3E%20W2%5B%22%E4%B8%9A%E5%8A%A1%E4%BB%A5%E6%AD%A3%E5%B8%B8%E8%8A%82%E5%A5%8F%E6%8E%A8%E8%BF%9B%E7%9A%84%E8%AF%81%E6%8D%AE%22%5D%0A%20%20E3%20--%3E%20W3%5B%22%E4%B8%BB%E5%BE%AA%E7%8E%AF%E6%88%96%E4%BB%BB%E5%8A%A1%E5%8D%A1%E6%AD%BB%E7%9A%84%E6%9C%80%E5%90%8E%E8%A3%81%E5%86%B3%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写的是单点失效的工程兜底，不写高安全等级的冗余：双通道表决、安全完整性等级的形式化论证是另一套体系，看门狗在那里只是最后一环。ECC 与存储器保护在软错误一课已讲，看门狗不纠错，只止损。内部狗可被错误代码关闭，外部狗芯片连着复位线，选型取决于你信不信自己的代码。最后一条纪律：看门狗路径必须在台架上实测——故意挂起主循环、故意饿死一个任务，观察安全状态与复位日志是否如期出现；没演练过的失效路径，等价于不存在。</p><p><span class="marginnote">初学者容易以为看门狗复位就等于「修好了」；复位只是失忆重启，bug 还在原地。没有失效日志与恢复梯子的设备，会陷进「复位—复现—复位」的死循环，用户看到的就是灯一直闪、永远连不上——复位是止损，不是修复。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>看门狗是独立时钟域的倒数器，监控的是「业务在推进」，不是「指令在执行」。</li><li>喂狗绑定全任务心跳；窗口看门狗把喂得太勤也判死，堵住盲目喂狗的路径。</li><li>复位前先落安全状态，复位后凭原因寄存器与备份日志走恢复，缺一级就打转。</li><li>独立看门狗与深睡档互斥，功耗与看门狗要一起设计，不能各自为政。</li><li>出处：各 MCU 参考手册 IWDG/WWDG 章节；IEC 61508 基础概念；据本栏 soft-error-ecc 一课与心跳喂狗实践整理。</li></ul>',5))])}const g=n(d,[["render",p]]);export{F as __pageData,g as default};
